          "replace": "            \"sequence_readout\": \"gru_0.85_causal_mean_0.15_half_life_3\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":",
